INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 87, 'Cited in Una Roberts Lawrence, Lottie Moon (1927)', 'As you wind your way from village to village you feel it is no idle fancy that the Master walks beside you.', 'presence,mission,faith,comfort', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 87 AND text = 'As you wind your way from village to village you feel it is no idle fancy that the Master walks beside you.');
